const cssContent = `.semequinho g{transform-box:fill-box;transform-origin:center}
.semequinho g.root{transform-box:view-box;transform-origin:0 0}
/* mascote */
.semequinho .m-in{transform-origin:50% 100%;animation:mIn .9s cubic-bezier(.34,1.56,.64,1) both}
.semequinho .m-bob{transform-origin:50% 100%;animation:bob 3s ease-in-out 1s infinite}
.semequinho .eyes{animation:blink 4.2s ease-in-out 1.6s infinite}
.semequinho .shine{transform:translateX(-120px);animation:shine 5s cubic-bezier(.45,0,.2,1) 2s infinite}
/* arcos: traço desenhando + brilho percorrendo */
.semequinho .draw{fill:none;stroke:#fff;stroke-width:44;stroke-dasharray:100 100;stroke-dashoffset:100;animation:draw .8s cubic-bezier(.65,0,.35,1) var(--d) forwards}
.semequinho .glint{fill:none;stroke:#fff;stroke-width:44;stroke-linecap:round;stroke-dasharray:16 200;stroke-dashoffset:16;animation:glint 5s cubic-bezier(.45,0,.55,1) var(--g) infinite}
/* ícones (no lugar) */
.semequinho .ic-in{animation:spawn .9s cubic-bezier(.34,1.56,.64,1) var(--d) both}
.semequinho .ic-idle{animation:idle 3.2s ease-in-out calc(2s + var(--i)) infinite}
.semequinho .ic-jump{transform-origin:50% 100%;animation:jump 6s linear var(--j) infinite}
/* brilhos */
.semequinho .sp-in{animation:pop .5s cubic-bezier(.34,1.8,.64,1) var(--d) both}
.semequinho .plus{animation:twinkle 2.4s ease-in-out calc(2.4s + var(--t)) infinite}
.semequinho .dot{animation:blinkDot 2.2s ease-in-out calc(2.4s + var(--t)) infinite}

@keyframes mIn{0%{transform:translateY(60px) scale(.4,.2);opacity:0}45%{opacity:1;transform:translateY(-14px) scale(.95,1.08)}70%{transform:translateY(0) scale(1.04,.96)}100%{transform:none}}
@keyframes bob{0%,100%{transform:translateY(0) scale(1,1)}50%{transform:translateY(-8px) scale(1,1.012)}}
@keyframes blink{0%,90%,100%{transform:scaleY(1)}93%{transform:scaleY(.1)}96%{transform:scaleY(1)}}
@keyframes shine{0%,50%{transform:translateX(-120px)}90%,100%{transform:translateX(460px)}}
@keyframes draw{to{stroke-dashoffset:0}}
@keyframes glint{0%{stroke-dashoffset:16}35%,100%{stroke-dashoffset:-100}}
@keyframes spawn{0%{opacity:0;transform:translateY(-40px) scale(.3) rotate(-12deg)}55%{opacity:1}100%{opacity:1;transform:none}}
@keyframes idle{0%,100%{transform:translateY(0) rotate(0)}50%{transform:translateY(-9px) rotate(-1.5deg)}}
@keyframes jump{
  0%{transform:none;animation-timing-function:ease-out}
  3%{transform:scale(1.07,.9);animation-timing-function:ease-in-out}
  6%{transform:translateY(-4px) scale(.95,1.07);animation-timing-function:cubic-bezier(.2,.7,.4,1)}
  11%{transform:translateY(-34px) scale(1,1);animation-timing-function:cubic-bezier(.6,0,.8,.3)}
  16%{transform:translateY(0) scale(1.08,.9);animation-timing-function:ease-out}
  20%{transform:scale(.98,1.03);animation-timing-function:ease-in-out}
  23%,100%{transform:none}}
@keyframes pop{0%{transform:scale(0)}100%{transform:none}}
@keyframes twinkle{0%,100%{transform:scale(1)}50%{transform:scale(.7)}}
@keyframes blinkDot{0%,100%{opacity:1}50%{opacity:.3}}
@media (prefers-reduced-motion:reduce){.semequinho *{animation:none!important}.semequinho .draw{stroke-dashoffset:0}}
/* digitando */
.semequinho .hand{transform-origin:96% 55%;animation:type 1.6s ease-in-out 1s infinite}
.semequinho .key{opacity:0;animation:key 1.6s ease-out 1s infinite;animation-delay:calc(1s + var(--k) * .3s)}
.semequinho .screenglow{animation:glow 1.6s ease-in-out 1s infinite}
.semequinho .code{opacity:0;animation:code 3.3s cubic-bezier(.2,.6,.3,1) var(--c) infinite}
@keyframes type{
 0%,100%{transform:rotate(0)}
 8%{transform:rotate(4.2deg)}14%{transform:rotate(0)}
 22%{transform:rotate(3.1deg)}28%{transform:rotate(0)}
 34%{transform:rotate(4.7deg)}40%{transform:rotate(-.4deg)}
 52%{transform:rotate(2.6deg)}58%{transform:rotate(0)}
 64%{transform:rotate(3.9deg)}70%{transform:rotate(0)}
 80%{transform:rotate(1.6deg)}}
@keyframes key{0%,12%{opacity:0}15%{opacity:1}35%,100%{opacity:0}}
@keyframes glow{0%,100%{opacity:.6}20%{opacity:1}45%{opacity:.7}70%{opacity:.95}}
@keyframes code{0%{opacity:0;transform:translate(0,10px) scale(.6)}15%{opacity:1;transform:translate(0,0) scale(1)}100%{opacity:0;transform:translate(var(--x),-110px) scale(1.1)}}
`;

export default function SemequinhoAnimation({ className }) {
  return (
    <div className={className} style={{ width: "100%", maxWidth: 640 }}>
      <style dangerouslySetInnerHTML={{ __html: cssContent }} />
      <div dangerouslySetInnerHTML={{ __html: svgContent }} />
    </div>
  );
}
